(3508, 'amity', 'Amity', 'amity', '<i>n.</i>', 'Am\"i*ty', '([uCode:?])', '; <i>pl.</i>\r <plw><b>Amities</b></plw> ([uCode:?]). [F. <i>amiti[uCode:eacute]</i>, OF.\r <i>amisti[uCode:eacute]</i>, <i>amist[uCode:eacute]</i>, fr. an assumed LL.\r <i>amisitas</i>, fr. L. <i>amicus</i> friendly, from <i>amare</i> to love.\r See <u>Amiab', 49, 0),
(3509, 'amma', 'Amma', 'amma', '<i>n.</i>', '||Am\"ma', '([uCode:?])', '[LL. <i>amma</i>, prob. of\r interjectional or imitative origin: cf. Sp. <i>ama</i>, G. <i>amme</i>,\r nurse, Basque <i>ama</i> mother, Heb. <i>[uCode:?]m</i>, Ar. <i>immun</i>,\r <i>ummun</i>.]', 49, 0),
