(14968, 'carob', 'Carob', 'carob', '<i>n.</i>', 'Car\"ob', '(?)', '[Cf. F.\r <i>caroube</i> fruit of the carob tree, Sp. <i>garrobo</i>,\r <i>al-garrobo</i>, carob tree, fr. Ar. <i>kharr[uCode:umacr]b</i>, Per.\r <i>Kharn[uCode:umacr]b</i>. Cf. <u>Clgaroba</u>.]', 219, 0),
(14969, 'caroche', 'Caroche', 'caroche', '<i>n.</i>', 'Ca*roche\"', '(?)', '[OF.\r <i>carrache</i>, F. <i>carrose</i> from It. <i>carrocio</i>,\r <i>carrozza</i>, fr. <i>carro</i>, L. <i>carus</i>. See\r <u>Car</u>.]', 219, 0),
