(17880, 'clare-obscure', 'Clare-obscure', 'clareobscure', '<i>n.</i>', 'Clare\"-ob*scure\"', '(?)', '[L.\r <i>clarus</i> clear + <i>obscurus</i> obscure; cf. F. <i>clair-\r obscur</i>. Cf. <u>Chiaroscuro</u>.] <i>(Painting)</i>', 262, 0),
(17881, 'claret', 'Claret', 'claret', '<i>n.</i>', 'Clar\"et', '(kl[uCode:abreve]r\"[uCode:ebreve]t)', '[OE. <i>claret</i>, <i>clare</i>, <i>clarry</i>, OF.\r <i>claret</i>, <i>clar[uCode:eacute]</i>, fr. <i>cler</i>, F.\r <i>clair</i>, clear, fr. L. <i>clarus</i> clear. See\r <u>Clear</u>.]', 262, 0),
(17882, 'claribella', 'Claribella', 'claribella', '<i>n.</i>', 'Clar`i*bel\"la', '(?)', '[NL., from L.\r <i>clarus</i> clear + <i>bellus</i> fine.] <i>(Mus.)</i>', 262, 0),
(17883, 'clarichord', 'Clarichord', 'clarichord', '<i>n.</i>', 'Clar\"i*chord', '(?)', '[F.\r <i>clatocorde</i>, fr.L. <i>clarus</i> clear + <i>chorda</i>\r string. See <u>Chord</u>.]', 262, 0),
(17884, 'clarification', 'Clarification', 'clarification', '<i>n.</i>', 'Clar`i*fi*ca\"tion', '(?)', '[Cf. F.\r <i>clarification</i>, L. <i>clarificatio</i> glorification.]', 262, 0),
(17885, 'clarifier', 'Clarifier', 'clarifier', '<i>n.</i>', 'Clar\"i*fi`er', '(?)', '', 262, 0),
(17886, 'clarify', 'Clarify', 'clarify', '<i>v. t.</i>', 'Clar\"i*fy', '(?)', '[<pos><i>imp.\r [uCode: p. p.</i></pos> <u>Clarified</u> (?)] <pos><i>p. pr. [uCode: vb.\r n.</i></pos> <u>Clarifying</u>.] [F. <i>clarifier</i>, from L.\r <i>clarificare</i>] <i>clarus</i> clear + <i>facere</i> to make.\r See <u>Clear</u>, and <u>Fact</u>.]', 262, 0),
