(17890, 'clarino', 'Clarino', 'clarino', '<i>n.</i>', '||Cla*ri\"no', '(?)', '[It. a\r trumpet.] <i>(Mus.)</i>', 262, 0),
(17891, 'clarion', 'Clarion', 'clarion', '<i>n.</i>', 'Clar\"i*on', '(?)', '[OE.\r <i>clarioun</i>, OF. <i>clarion</i>, F. <i>clairon</i>, LL.\r <i>clario</i>, <i>claro</i>; so called from its clear tone, fr.\r L. <i>clarus</i> clear. See <u>Clear</u>.]', 262, 0),
