(26935, 'diapason', 'Diapason', 'diapason', '<i>n.</i>', 'Di`a*pa\"son', '(?)', '[L., fr. Gr.\r <grk>diapasw^n</grk> (<i>i. e.</i>, <grk>\"h dia` pasw^n chordw^n\r symfoni`a</grk> the concord of the first and last notes, the octave);\r <grk>dia`</grk> through + <grk>pasw^n</grk>, gen. pl. of\r <grk>pa^s</grk> all: cf. F. <i>diapason</i>.', 406, 0),
(26936, 'diapedesis', 'Diapedesis', 'diapedesis', '<i>n.</i>', '||Di`a*pe*de\"sis', '(?)', '[NL., fr. Gr.\r [uCode:?] a leaping or oozing through, fr. [uCode:?] to leap through;\r <grk>dia`</grk> through + [uCode:?] to leap.] <i>(Med.)</i>', 406, 0),
(26937, 'diapente', 'Diapente', 'diapente', '<i>n.</i>', '||Di`a*pen\"te', '(?)', '[L., fr. Gr. [uCode:?]\r a fifth; <grk>dia`</grk> through + [uCode:?] five: cf. F. <i>diapente</i>.]', 406, 0),
(26938, 'diaper', 'Diaper', 'diaper', '<i>n.</i>', 'Di\"a*per', '(?)', '[OF. <i>diaspre</i>,\r <i>diapre</i>, <i>diaspe</i>, sort of figured cloth, It.\r <i>diaspro</i> jasper, <i>diaspo</i> figured cloth, from L.\r <i>jaspis</i> a green-colored precious stone. See <u>Jasper</u>.]', 407, 0),
