(30624, 'duramen', 'Duramen', 'duramen', '<i>n.</i>', '||Du*ra\"men', '(?)', '[L., hardness, a\r hardened, <i>i. e.</i>, ligneous, vine branch, fr. <i>durare</i> to\r harden. See <u>Dure</u>.] <i>(Bot.)</i>', 462, 0),
(30625, 'durance', 'Durance', 'durance', '<i>n.</i>', 'Dur\"ance', '(?)', '[OF. <i>durance</i>\r duration, fr. L. <i>durans</i>, <i>-antis</i>, p. pr. <i>durare</i>\r to endure, last. See <u>Dure</u>, and cf. <u>Durant</u>.]', 462, 0);
