(35199, 'exility', 'Exility', 'exility', '<i>n.</i>', 'Ex*il\"ity', '(?)', '[L. <i>exilitas</i>:\r cf. F. <i>exilit[uCode:eacute]</i>. See <u>Exile</u>, <pos><i>a.</i></pos>]', 525, 0),
(35200, 'eximious', 'Eximious', 'eximious', '<i>a.</i>', 'Ex*im\"ious', '', '', 525, 0),
(35201, 'exinanite', 'Exinanite', 'exinanite', '<i>v. t.</i>', 'Ex*in\"a*nite', '(?)', '[L.\r <i>exinanitus</i>, p. p. of <i>exinanire</i>; <i>ex</i> out (intens.)\r + <i>inanire</i> to make empty, <i>inanis</i>, empty.]', 525, 0),
(35202, 'exinanition', 'Exinanition', 'exinanition', '<i>n.</i>', 'Ex*in`a*ni\"tion', '', '', 525, 0),
