(37011, 'feuter', 'feuter', 'feuter', '<i>v. t.</i>', 'feu\"ter', '([uCode:?])', '[OE. <i>feutre</i>\r rest for a lance, OF. <i>feutre</i>, <i>fautre</i>, <i>feltre</i>,\r felt, cushion, rest for a lance, fr. LL. <i>filtrum</i>,\r <i>feltrum</i>; of German origin, and akin to E. <i>felt</i>. See\r <u>Felt</u>, and cf. <u>Filter</u>.]', 555, 0),
(37012, 'feuterer', 'Feuterer', 'feuterer', '<i>n.</i>', 'Feu\"ter*er', '(?)', '[Either fr. G.\r <i>f[uCode:uuml]tterer</i> feeder, or corrupted fr. OF. <i>vautrier</i>,\r <i>vaultrier</i>; fr. vaultre, viautre, a kind of hound, fr. L.\r <i>vertragus</i>, <i>vertraga</i>, a greyhound. The last is of Celtic\r origin.]', 555, 0),
(37013, 'fever', 'Fever', 'fever', '<i>n.</i>', 'Fe\"ver', '(?)', '[OE. <i>fever</i>,\r <i>fefer</i>, AS. <i>fefer</i>, <i>fefor</i>, L. <i>febris</i>: cf.\r F. <i>fi[uCode:egrave]vre</i>.  Cf. <u>Febrile</u>.]', 555, 0),
