(99141, 'tactics', 'Tactics', 'tactics', '<i>n.</i>', 'Tac\"tics', '(?)', '[Gr. [uCode:?], pl., and [uCode:?] (sc.\r [uCode:?], sing., fr. [uCode:?] fit for ordering or arranging, fr. [uCode:?], [uCode:?], to put in\r order, to arrange: cf. F. <i>tactique</i>.]', 1468, 0),
(99142, 'tactile', 'Tactile', 'tactile', '<i>a.</i>', 'Tac\"tile', '(?)', '[L. <i>tactilis</i>, fr.\r <i>tangere</i>, <i>tactum</i>, to touch: cf. F. <i>tactile</i>.]', 1468, 0),
