(101767, 'tincture', 'Tincture', 'tincture', '<i>n.</i>', 'Tinc\"ture', '(?)', '[L. <i>tinctura</i> a\r dyeing, from <i>tingere</i>, <i>tinctum</i>, to tinge, dye: cf. OE.\r <i>tainture</i>, <i>teinture</i>, F. <i>teinture</i>, L. <i>tinctura</i>.\r See <u>Tinge</u>.]', 1510, 0),
(101768, 'tincture', 'Tincture', 'tincture', '<i>v. t.</i>', 'Tinc\"ture', '', '', 1510, 0),
(101769, 'tind', 'Tind', 'tind', '<i>v. t.</i>', 'Tind', '(?)', '[OE. <i>tenden</i>, AS.\r <i>tendan</i>; akin to G. <i>z[uCode:uuml]nden</i>, OHG. <i>zunten</i>, Icel.\r <i>tendra</i>, Sw. <i>t[uCode:auml]nda</i>, Dan. <i>t[uCode:aelig]nde</i>, Goth.\r <i>tandjan</i> to kindle, <i>tundnan</i> to be kindled, to burn.  Cf.', 1510, 0),
(101770, 'tindal', 'Tindal', 'tindal', '<i>n.</i>', 'Tin\"dal', '(?)', '[From the native name: cf.\r Malayalam <i>ta[uCode:?][uCode:?]al</i>.]', 1510, 0),
(101771, 'tinder', 'Tinder', 'tinder', '<i>n.</i>', 'Tin\"der', '(?)', '[OE. <i>tinder</i>,\r <i>tunder</i>, AS. <i>tynder</i>, <i>tyndre</i>; akin to <i>tendan</i> to\r kindle, D. <i>tonder</i> tinder, G. <i>zunder</i>, OHG. <i>zuntara</i>,\r <i>zuntra</i>, Icel. <i>tundr</i>, Sw. <i>tunder</i>, Dan.\r <i>t[uCode:ouml]nder</i>.', 1511, 0),
