(107818, 'vaticide', 'Vaticide', 'vaticide', '<i>n.</i>', 'Vat\"i*cide', '(?)', '[L. <i>vates</i> a prophet\r + <i>caedere</i> to kill.]', 1597, 0),
(107819, 'vaticinal', 'Vaticinal', 'vaticinal', '<i>a.</i>', 'Va*tic\"i*nal', '(?)', '[See <u>Vaticinate</u>.]', 1597, 0),
(107820, 'vaticinate', 'Vaticinate', 'vaticinate', '<i>v. i. [uCode: t.</i>', 'Va*tic\"i*nate', '(?)', '[L.\r <i>vaticinatus</i>, p. p. of <i>vaticinari</i> to prophesy, fr.\r <i>vaticinus</i> prophetical, fr. <i>vates</i> a prophet.]', 1597, 0),
(107821, 'vaticination', 'Vaticination', 'vaticination', '<i>n.</i>', 'Va*tic`i*na\"tion', '(?)', '[L.\r <i>vaticinatio</i>.]', 1597, 0),
