(107855, 'veal', 'Veal', 'veal', '<i>n.</i>', 'Veal', '(?)', '[OE. <i>veel</i>, OF.\r <i>veel</i>, F. <i>veau</i>, L. <i>vitellus</i>, dim. of <i>vitulus</i> a\r calf; akin to E. <i>wether</i>. See <u>Wether</u>, and cf. <u>Vellum</u>,\r <u>Vituline</u>.]', 1597, 0),
(107856, 'vection', 'Vection', 'vection', '<i>n.</i>', 'Vec\"tion', '(?)', '[L. <i>vectio</i>, from\r <i>vehere</i>, <i>vectum</i>, to carry.]', 1597, 0),
(107857, 'vectitation', 'Vectitation', 'vectitation', '<i>n.</i>', 'Vec`ti*ta\"tion', '(?)', '[L. <i>vectitatus</i>\r born[uCode:?] about, fr. <i>ve[uCode:?]tare</i>, v. intens. fr. <i>vehere</i>,\r <i>vectum</i>, to carry.]', 1597, 0),
(107858, 'vector', 'Vector', 'vector', '<i>n.</i>', 'Vec\"tor', '(?)', '[L., a bearer, carrier. fr.\r <i>vehere</i>, <i>vectum</i>, to carry.]', 1597, 0),
(107859, 'vecture', 'Vecture', 'vecture', '<i>n.</i>', 'Vec\"ture', '(?)', '[L. <i>vectura</i>, from\r <i>vehere</i>, <i>vectum</i>, to carry.  Cf. <u>Vettura</u>,\r <u>Voiture</u>.]', 1597, 0),
(107860, 'veda', 'Veda', 'veda', '<i>n.</i>', 'Ve\"da', '(?; 277)', '[Skr. <i>v[uCode:?]da</i>,\r properly, knowledge, from <i>vid</i> to know. See <u>Wit</u>.]', 1597, 0),
