(108126, 'verdant', 'Verdant', 'verdant', '<i>a.</i>', 'Ver\"dant', '(?)', '[F. <i>verdoyant</i>, p. pr.\r of <i>verdoyer</i> to be verdant, to grow green, OF. <i>verdoier</i>,\r <i>verdeier</i>, fr. <i>verd</i>, <i>vert</i>, green, fr. L. <i>viridis</i>\r green, fr. <i>virere</i> to be green: cf. OF. <i>verdant</i> verdant, L.\r <i>', 1602, 0),
(108127, 'verd antique', 'Verd antique', 'verdantique', '', 'Verd` an*tique\"', '(?). [F. <i>vert antique</i> a kind of marble;\r <i>verd</i>, <i>vert</i>, green + <i>antique</i> ancient: cf. It. <i>verde\r antico</i>.] <i>(Min.)</i> <sd><i>(a)</i></sd> )', '', 1602, 0),
(108128, 'verdantly', 'Verdantly', 'verdantly', '<i>adv.</i>', 'Ver\"dant*ly', '(?)', '', 1602, 0),
