(108177, 'vermeology', 'Vermeology', 'vermeology', '<i>n.</i>', 'Ver`me*ol\"o*gy', '(?)', '[L. <i>vermes</i>\r worms + <i>-logy</i>.] <i>(Zo[uCode:ouml]l.)</i>', 1603, 0),
(108178, 'vermes', 'Vermes', 'vermes', '<i>n. pl.</i>', '||Ver\"mes', '(?)', '[L. <i>vermes</i>, pl.\r of <i>vermis</i> a worm.] <i>(Zo[uCode:ouml]l.)</i> <sd><i>(a)</i></sd>', 1603, 0),
(108179, 'vermetid', 'Vermetid', 'vermetid', '<i>n.</i>', 'Ver\"me*tid', '(?)', '<i>(Zo[uCode:ouml]l.)</i>', 1603, 0),
(108180, 'vermetus', 'Vermetus', 'vermetus', '<i>n.</i>', '||Ver*me\"tus', '(?)', '[NL., from L.\r <i>vermis</i> worm.] <i>(Zo[uCode:ouml]l.)</i>', 1603, 0),
(108181, 'vermicelli', 'Vermicelli', 'vermicelli', '<i>n.</i>', 'Ver`mi*cel\"li', '(?)', '[It., pl. of\r <i>vermicello</i>, literally, a little worm, dim. of <i>verme</i> a worm,\r L. <i>vermis</i>.  See <u>Worm</u>, and cf. <u>Vermicule</u>,\r <u>Vermeil</u>.]', 1603, 0),
(108182, 'vermicide', 'Vermicide', 'vermicide', '<i>n.</i>', 'Ver\"mi*cide', '(?)', '[L. <i>vermis</i> a worm\r + <i>caedere</i> to kill.]', 1603, 0),
(108183, 'vermicious', 'Vermicious', 'vermicious', '<i>a.</i>', 'Ver*mi\"cious', '(?)', '[L. <i>vermis</i> a\r worm.]', 1603, 0),
(108184, 'vermicular', 'Vermicular', 'vermicular', '<i>a.</i>', 'Ver*mic\"u*lar', '(?)', '[L. <i>vermiculus</i> a\r little worm, dim. of <i>vermis</i> a worm: cf. F. <i>vermiculaire</i>.  See\r <u>Vermicelli</u>.]', 1603, 0),
(108185, 'vermiculate', 'Vermiculate', 'vermiculate', '<i>v. t.</i>', 'Ver*mic\"u*late', '(?)', '[<pos><i>imp. [uCode: p.\r p.</i></pos> <u>Vermiculated</u> (?)] <pos><i>p. pr. [uCode: vb. n.</i></pos>\r <u>Vermiculating</u>.] [L. <i>vermiculatus</i> inlaid so as to resemble the\r tracks of worms, p. p. of <i>vermiculari</i> to be full of worms,\r <i>ver', 1603, 0),
(108186, 'vermiculate', 'Vermiculate', 'vermiculate', '<i>a.</i>', 'Ver*mic\"u*late', '(?)', '', 1603, 0),
(108187, 'vermiculated', 'Vermiculated', 'vermiculated', '<i>a.</i>', 'Ver*mic\"u*la`ted', '(?)', '', 1603, 0),
(108188, 'vermiculation', 'Vermiculation', 'vermiculation', '<i>n.</i>', 'Ver*mic`u*la\"tion', '(?)', '[L.\r <i>vermiculatio</i> a being worm-eaten.]', 1603, 0),
(108189, 'vermicule', 'Vermicule', 'vermicule', '<i>n.</i>', 'Ver\"mi*cule', '(?)', '[L. <i>vermiculus</i>,\r dim. of <i>vermis</i> a worm.  See <u>Vermicular</u>.]', 1603, 0),
(108190, 'vermiculite', 'Vermiculite', 'vermiculite', '<i>n.</i>', 'Ver*mic\"u*lite', '(?)', '[L. <i>vermiculus</i>,\r dim. of <i>vermis</i> worm.] <i>(Min.)</i>', 1603, 0),
(108191, 'vermiculose', 'Vermiculose', 'vermiculose', '<i>a.</i>', 'Ver*mic\"u*lose`', '(?)', '\r  [L. <i>vermiculosus</i>.  See <u>Vermicule</u>.]', 1603, 1),
(108193, 'vermiform', 'Vermiform', 'vermiform', '<i>a.</i>', 'Ver\"mi*form', '(?)', '[L. <i>vermis</i> a worm\r +  <i>-form</i>.]', 1603, 0),
(108194, 'vermiformia', 'Vermiformia', 'vermiformia', '<i>n. pl.</i>', '||Ver`mi*for\"mi*a', '(?)', '[NL.]\r <i>(Zo[uCode:ouml]l.)</i>', 1603, 0),
(108195, 'vermifugal', 'Vermifugal', 'vermifugal', '<i>a.</i>', 'Ver*mif\"u*gal', '(?)', '[L. <i>vermis</i> a\r worm + <i>fugare</i> to drive away, fr. <i>fugere</i> to flee.  See\r <u>Worm</u>, and <u>Fugitive</u>.] <i>(Med.)</i>', 1603, 0),
(108196, 'vermifuge', 'Vermifuge', 'vermifuge', '<i>n.</i>', 'Ver\"mi*fuge', '(?)', '[Cf. F. <i>vermifuge</i>.\r See <u>Vermifugal</u>.] <i>(Med.)</i>', 1603, 0),
(108197, 'vermil', 'Vermil', 'vermil', '<i>n.</i>', 'Ver\"mil', '(?)', '', 1603, 0),
(108198, 'vermilinguia', 'Vermilinguia', 'vermilinguia', '<i>n. pl.</i>', '||Ver`mi*lin\"gui*a', '(?)', '[NL., fr. L.\r <i>vermis</i> worm + <i>lingua</i> tongue.] [Called also\r <i>Vermilingues</i>.] <i>(Zo[uCode:ouml]l.)</i> <sd><i>(a)</i></sd>', 1603, 0),
