(108202, 'vermin', 'Vermin', 'vermin', '<i>n. sing. [uCode: pl.</i>', 'Ver\"min', '(?)', '] used chiefly as\r plural. [OE. <i>vermine</i>, F. <i>vermine</i>, from L. <i>vermis</i> a\r worm; cf. LL. <i>vermen</i> a worm, L. <i>verminosus</i> full of worms.\r See <u>Vermicular</u>, <u>Worm</u>.]', 1603, 0),
(108203, 'verminate', 'Verminate', 'verminate', '<i>v. i.</i>', 'Ver\"mi*nate', '(?)', '[L. <i>verminare</i>\r to have worms, fr. <i>vermis</i> a worm.]', 1603, 0),
(108204, 'vermination', 'Vermination', 'vermination', '<i>n.</i>', 'Ver`mi*na\"tion', '(?)', '[L. <i>verminatio</i>\r the worms, a disease of animals, a crawling, itching pain.]', 1603, 0),
